import type { ChoiceDef, Ctx, EventDef } from '../types';
import type { Need } from '../../engine/continuity';
import { near, opt, out, pickParent, tt, trCase, Kw, heK, HeK, type Form } from './young-kit';
import { afford, noMourn, partnerWord, setPartner } from './adult-kit';
import { officeJob, workKind, wage } from './util';

// Body wave: illness, injuries, check-ups, bills, sleep, stress, drink, smoking and ageing, ages 10-90. Punchy
// outcomes that move health, happiness or money. Nothing graphic, no recipes, no real brands. Help is always one
// of the choices and usually the sensible one. RNG only through c.rng, same calls in both languages.
// Flags: bd_smoker (started smoking or vaping; cleared by quitting), bd_gym (joined a gym).

const SMOKER = 'bd_smoker';
const smoker = (c: Ctx) => c.h.has(SMOKER);
const employed = (c: Ctx) => !!c.p.jobId && !c.p.retired;
const costly = (usd: number) => ({ requires: (c: Ctx) => afford(c, wage(c, usd)), requiresLabel: 'Not enough money' });

/** The partner as a noun phrase in the story language, with a Turkish case ("karına"); English genitive adds 's. */
const pw = (c: Ctx, form: Form = 'nom') => {
  const w = partnerWord(c);
  return c.lang === 'tr' ? trCase(w, form) : w + (form === 'gen' ? "'s" : '');
};

interface Spec {
  age: [number, number];
  w: number;
  cd?: number;
  max?: number;
  once?: boolean;
  when?: (c: Ctx) => boolean;
  needs?: Need[];
  setup?: (c: Ctx) => void;
}

function ev(id: string, s: Spec, title: [string, string], text: [string, string] | ((c: Ctx) => string), choices: ChoiceDef[]): EventDef {
  return {
    id: 'base.bd_' + id,
    category: 'health',
    minAge: s.age[0],
    maxAge: s.age[1],
    weight: s.w,
    cooldown: s.cd ?? 5,
    maxPerLife: s.max ?? 2,
    once: s.once,
    needs: s.needs,
    setup: s.setup,
    when: s.when ? (c) => noMourn(c) && s.when!(c) : noMourn,
    title: tt(title[0], title[1]),
    text: typeof text === 'function' ? text : tt(text[0], text[1]),
    choices,
  };
}

